args.content:
import re

errors = []
warnings = []
starts = []
hour_counts = {}

with open('/root/.nanobot/logs/gateway.log') as f:
    for line in f:
        if '2026-05-22' not in line:
            continue
        m = re.match(r'(\d{4}-\d{2}-\d{2} (\d{2}):\d{2}:\d{2}\.\d+) \| (\w+)', line)
        if m:
            ts, hour, level = m.group(1), m.group(2), m.group(3)
            hour_counts[hour] = hour_counts.get(hour, 0) + 1
            if level == 'ERROR':
                errors.append(line.strip()[:200])
            elif level == 'WARNING':
                warnings.append(line.strip()[:200])
            if any(k in line.lower() for k in ['listen', 'server start', 'boot', 'shutdown', 'restart']):
                starts.append(line.strip()[:200])

print(f'=== True ERROR: {len(errors)} ===')
for e in errors:
    print(e)
print(f'\n=== True WARNING: {len(warnings)} ===')
for w in warnings:
    print(w)
print(f'\n=== Gateway lifecycle events: {len(starts)} ===')
for s in starts:
    print(s)
print(f'\n=== Hour distribution ===')
for h in range(24):
    hh = f'{h:02d}'
    c = hour_counts.get(hh, 0)
    bar = '#' * min(c, 50)
    print(f'  {hh}:00  {c:>6}  {bar}')

